#!/usr/bin/env python3
"""news-image-20261118 V3 — Wednesday 18 November 2026 front page, 44 stories.

Writes entry.png (embedded below as zlib-compressed base64). Python 3.13
stdlib only. Output goes to $MAKEFUN_OUTPUT_DIR, else /output, else output/.
"""
import base64
import os
import zlib

DATA = [
    '',
    '',
    '',
    '',
    ''
]


def main():
    raw = zlib.decompress(base64.b64decode("".join(DATA)))
    out = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if out:
        path = os.path.join(out, "entry.png")
    elif os.path.isdir("/output"):
        path = "/output/entry.png"
    else:
        os.makedirs("output", exist_ok=True)
        path = os.path.join("output", "entry.png")
    with open(path, "wb") as f:
        f.write(raw)


if __name__ == "__main__":
    main()
